export const VERSETS = {
  'nur-30': { s: 24, a: '30', sourate: 'An-Nour', ar: 'قُل لِّلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ۚ ذَٰلِكَ أَزْكَىٰ لَهُمْ ۗ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ', fr: "Dis aux croyants de baisser leurs regards et de préserver leur chasteté. C'est plus pur pour eux. Allah est parfaitement informé de ce qu'ils font." },
  'nur-31': { s: 24, a: '31', sourate: 'An-Nour', fr: "Et dis aux croyantes de baisser leurs regards, de préserver leur chasteté, et de ne montrer de leurs atours que ce qui en paraît, et qu'elles rabattent leur voile (khimar) sur leurs poitrines… Et repentez-vous tous devant Allah, ô croyants, afin que vous réussissiez." },
  'nur-15': { s: 24, a: '15', sourate: 'An-Nour', fr: "…Vous le considériez comme une chose insignifiante, alors qu'auprès d'Allah c'était énorme." },
  'nur-19': { s: 24, a: '19', sourate: 'An-Nour', fr: "Ceux qui aiment que la turpitude se propage parmi les croyants auront un châtiment douloureux ici-bas et dans l'au-delà. Allah sait, et vous ne savez pas." },
  'nur-21': { s: 24, a: '21', sourate: 'An-Nour', fr: "Ô vous qui avez cru ! Ne suivez pas les pas du Diable. Quiconque suit les pas du Diable, [qu'il sache que] celui-ci ordonne la turpitude et le blâmable." },
  'isra-32': { s: 17, a: '32', sourate: 'Al-Isra', ar: 'وَلَا تَقْرَبُوا الزِّنَىٰ ۖ إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا', fr: "Et n'approchez pas la fornication. C'est vraiment une turpitude, et quel mauvais chemin !" },
  'isra-36': { s: 17, a: '36', sourate: 'Al-Isra', fr: "Ne poursuis pas ce dont tu n'as aucune connaissance. L'ouïe, la vue et le cœur : sur tout cela, on sera certes interrogé." },
  'isra-23': { s: 17, a: '23-24', sourate: 'Al-Isra', fr: "Ton Seigneur a décrété : « N'adorez que Lui, et soyez bienfaisants envers vos père et mère. Si l'un d'eux ou tous deux atteignent la vieillesse auprès de toi, ne leur dis point « Fi ! », ne les brusque pas, et adresse-leur des paroles respectueuses. Abaisse pour eux, par miséricorde, l'aile de l'humilité, et dis : « Seigneur, fais-leur miséricorde comme ils m'ont élevé tout petit. »" },
  'isra-53': { s: 17, a: '53', sourate: 'Al-Isra', fr: "Dis à Mes serviteurs de prononcer les meilleures paroles, car le Diable sème la discorde entre eux. Le Diable est certes pour l'homme un ennemi déclaré." },
  'ahzab-59': { s: 33, a: '59', sourate: 'Al-Ahzab', fr: "Ô Prophète ! Dis à tes épouses, à tes filles et aux femmes des croyants de ramener sur elles leurs grands voiles (jalabib) : elles en seront plus vite reconnues et éviteront d'être offensées. Allah est Pardonneur et Miséricordieux." },
  'ahzab-35': { s: 33, a: '35', sourate: 'Al-Ahzab', fr: "…les hommes et les femmes qui évoquent souvent Allah : Allah a préparé pour eux un pardon et une énorme récompense." },
  'araf-26': { s: 7, a: '26', sourate: "Al-A'raf", fr: "Ô enfants d'Adam ! Nous avons fait descendre sur vous un vêtement pour cacher votre nudité, ainsi que des parures. Mais le vêtement de la piété, voilà ce qui est meilleur." },
  'araf-23': { s: 7, a: '23', sourate: "Al-A'raf", ar: 'رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', fr: "Ils dirent : « Notre Seigneur, nous avons fait du tort à nous-mêmes. Si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants. »" },
  'araf-200': { s: 7, a: '200-201', sourate: "Al-A'raf", fr: "Et si jamais le Diable t'incite à faire le mal, cherche refuge auprès d'Allah : Il entend et sait tout. Ceux qui craignent Allah, lorsqu'une suggestion du Diable les touche, se rappellent [Allah] et les voilà devenus clairvoyants." },
  'araf-156': { s: 7, a: '156', sourate: "Al-A'raf", ar: 'وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ', fr: "…Et Ma miséricorde embrasse toute chose." },
  'hujurat-12': { s: 49, a: '12', sourate: 'Al-Hujurat', ar: 'وَلَا يَغْتَب بَّعْضُكُم بَعْضًا', fr: "Ô vous qui avez cru ! Évitez de trop conjecturer, car une partie des conjectures est péché. N'espionnez pas et ne médisez pas les uns des autres. L'un de vous aimerait-il manger la chair de son frère mort ? Vous en auriez horreur. Craignez Allah : Allah est Celui qui accepte le repentir, Miséricordieux." },
  'hujurat-11': { s: 49, a: '11', sourate: 'Al-Hujurat', fr: "Ô vous qui avez cru ! Qu'un groupe ne se moque pas d'un autre groupe : ceux-ci sont peut-être meilleurs qu'eux… Ne vous dénigrez pas et ne vous lancez pas mutuellement des sobriquets [injurieux]." },
  'hujurat-13': { s: 49, a: '13', sourate: 'Al-Hujurat', fr: "…Le plus noble d'entre vous, auprès d'Allah, est le plus pieux. Allah est certes Omniscient et Grand Connaisseur." },
  'luqman-18': { s: 31, a: '18', sourate: 'Luqman', fr: "Et ne détourne pas ton visage des gens [par mépris], et ne foule pas la terre avec arrogance : Allah n'aime pas le présomptueux plein de gloriole." },
  'mutaffifin-14': { s: 83, a: '14', sourate: 'Al-Mutaffifin', ar: 'كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا يَكْسِبُونَ', fr: "Pas du tout ! Mais ce qu'ils ont accompli a couvert leurs cœurs (comme une rouille)." },
  'hadid-16': { s: 57, a: '16', sourate: 'Al-Hadid', fr: "Le moment n'est-il pas venu pour ceux qui ont cru que leurs cœurs s'humilient à l'évocation d'Allah et devant ce qui est descendu de la vérité, et de ne pas être comme ceux qui ont reçu le Livre avant eux : le temps leur a paru long, leurs cœurs se sont endurcis…" },
  'hadid-20': { s: 57, a: '20', sourate: 'Al-Hadid', fr: "Sachez que la vie présente n'est que jeu, amusement, vaine parure, une course à l'orgueil entre vous et une rivalité dans l'acquisition des richesses et des enfants… Et la vie présente n'est que jouissance trompeuse." },
  'baqara-74': { s: 2, a: '74', sourate: 'Al-Baqara', fr: "Puis, après cela, vos cœurs se sont endurcis : ils sont comme des pierres, ou plus durs encore…" },
  'rad-28': { s: 13, a: '28', sourate: "Ar-Ra'd", ar: 'أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ', fr: "…N'est-ce pas par l'évocation d'Allah que les cœurs se tranquillisent ?" },
  'rad-11': { s: 13, a: '11', sourate: "Ar-Ra'd", ar: 'إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا مَا بِأَنفُسِهِمْ', fr: "…Allah ne modifie pas l'état d'un peuple tant que [les individus qui le composent] ne modifient pas ce qui est en eux-mêmes." },
  'taha-124': { s: 20, a: '124', sourate: 'Ta-Ha', fr: "Et quiconque se détourne de Mon rappel mènera certes une vie pleine de gêne, et Nous le ressusciterons aveugle le Jour de la Résurrection." },
  'hashr-19': { s: 59, a: '19', sourate: 'Al-Hashr', fr: "Et ne soyez pas comme ceux qui ont oublié Allah : [Allah] leur a alors fait oublier leurs propres personnes. Ceux-là sont les pervers." },
  'hashr-10': { s: 59, a: '10', sourate: 'Al-Hashr', ar: 'رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ', fr: "« Seigneur, pardonne-nous ainsi qu'à nos frères qui nous ont précédés dans la foi, et ne mets dans nos cœurs aucune rancœur envers ceux qui ont cru. Seigneur, Tu es Compatissant et Très Miséricordieux. »" },
  'fatir-6': { s: 35, a: '6', sourate: 'Fatir', ar: 'إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا', fr: "Le Diable est pour vous un ennemi : prenez-le donc pour ennemi. Il ne fait qu'appeler ses partisans pour qu'ils soient des gens de la Fournaise." },
  'baqara-268': { s: 2, a: '268', sourate: 'Al-Baqara', fr: "Le Diable vous fait craindre l'indigence et vous ordonne des actions honteuses, tandis qu'Allah vous promet pardon et grâce venant de Lui…" },
  'nahl-99': { s: 16, a: '99-100', sourate: 'An-Nahl', fr: "Il n'a aucun pouvoir sur ceux qui croient et placent leur confiance en leur Seigneur. Il n'a de pouvoir que sur ceux qui le prennent pour allié…" },
  'hijr-39': { s: 15, a: '39-40', sourate: 'Al-Hijr', fr: "[Iblis] dit : « Seigneur, parce que Tu m'as égaré, je leur embellirai la vie sur terre et les égarerai tous, à l'exception de Tes serviteurs sincères parmi eux. »" },
  'ibrahim-22': { s: 14, a: '22', sourate: 'Ibrahim', fr: "Et lorsque tout sera accompli, le Diable dira : « …Je n'avais aucune autorité sur vous si ce n'est que je vous ai appelés et que vous m'avez répondu. Ne me faites donc pas de reproches, mais faites-en à vous-mêmes… »" },
  'ibrahim-7': { s: 14, a: '7', sourate: 'Ibrahim', ar: 'لَئِن شَكَرْتُمْ لَأَزِيدَنَّكُمْ', fr: "Et lorsque votre Seigneur proclama : « Si vous êtes reconnaissants, très certainement J'augmenterai [Mes bienfaits] pour vous. »" },
  'yusuf-53': { s: 12, a: '53', sourate: 'Yusuf', fr: "Je ne m'innocente cependant pas, car l'âme incite au mal, à moins que mon Seigneur, par miséricorde, [ne la protège]. Mon Seigneur est certes Pardonneur et Miséricordieux." },
  'nazi-40': { s: 79, a: '40-41', sourate: "An-Nazi'at", fr: "Et quant à celui qui aura redouté de comparaître devant son Seigneur et préservé son âme de la passion, le Paradis sera alors son refuge." },
  'jathiya-23': { s: 45, a: '23', sourate: 'Al-Jathiya', fr: "As-tu vu celui qui a fait de sa passion sa divinité ?…" },
  'imran-14': { s: 3, a: '14', sourate: "Al 'Imran", fr: "On a embelli aux gens l'amour des choses qu'ils désirent : femmes, enfants, trésors amassés d'or et d'argent… Tout cela est l'objet de jouissance pour la vie présente, alors que c'est auprès d'Allah qu'il y a le meilleur retour." },
  'imran-185': { s: 3, a: '185', sourate: "Al 'Imran", ar: 'كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ', fr: "Toute âme goûtera la mort. Et c'est seulement au Jour de la Résurrection que vous recevrez votre entière rétribution. Quiconque est écarté du Feu et introduit au Paradis a certes réussi. La vie présente n'est qu'un objet de jouissance trompeuse." },
  'imran-135': { s: 3, a: '135', sourate: "Al 'Imran", fr: "Et pour ceux qui, s'ils ont commis une turpitude ou fait du tort à eux-mêmes, se souviennent d'Allah et demandent pardon pour leurs péchés — et qui donc pardonne les péchés sinon Allah ? — et qui ne persistent pas sciemment dans ce qu'ils ont fait." },
  'imran-134': { s: 3, a: '134', sourate: "Al 'Imran", fr: "…ceux qui dépensent dans l'aisance et dans l'adversité, qui maîtrisent leur colère et pardonnent aux gens. Allah aime les bienfaisants." },
  'imran-133': { s: 3, a: '133', sourate: "Al 'Imran", fr: "Et hâtez-vous vers un pardon de votre Seigneur et vers un Paradis large comme les cieux et la terre, préparé pour les pieux." },
  'imran-159': { s: 3, a: '159', sourate: "Al 'Imran", fr: "C'est par quelque miséricorde de la part d'Allah que tu as été doux envers eux. Si tu avais été rude et au cœur dur, ils se seraient dispersés loin de toi…" },
  'imran-31': { s: 3, a: '31', sourate: "Al 'Imran", fr: "Dis : « Si vous aimez vraiment Allah, suivez-moi : Allah vous aimera alors et vous pardonnera vos péchés. Allah est Pardonneur et Miséricordieux. »" },
  'imran-8': { s: 3, a: '8', sourate: "Al 'Imran", ar: 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ', fr: "« Seigneur, ne laisse pas dévier nos cœurs après que Tu nous as guidés, et accorde-nous Ta miséricorde. C'est Toi, certes, le Grand Donateur. »" },
  'zalzala-7': { s: 99, a: '7-8', sourate: 'Az-Zalzala', ar: 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ ۝ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ', fr: "Quiconque fait un bien, fût-ce du poids d'un atome, le verra, et quiconque fait un mal, fût-ce du poids d'un atome, le verra." },
  'zumar-53': { s: 39, a: '53', sourate: 'Az-Zumar', ar: 'قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا مِن رَّحْمَةِ اللَّهِ ۚ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا ۚ إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ', fr: "Dis : « Ô Mes serviteurs qui avez commis des excès à votre propre détriment, ne désespérez pas de la miséricorde d'Allah. Allah pardonne tous les péchés. C'est Lui le Pardonneur, le Très Miséricordieux. »" },
  'zumar-10': { s: 39, a: '10', sourate: 'Az-Zumar', fr: "…Les endurants recevront leur pleine récompense sans compter." },
  'tahrim-8': { s: 66, a: '8', sourate: 'At-Tahrim', fr: "Ô vous qui avez cru ! Repentez-vous à Allah d'un repentir sincère (tawbatan nasuha). Il se peut que votre Seigneur efface vos méfaits et vous fasse entrer dans des jardins sous lesquels coulent les rivières…" },
  'tahrim-6': { s: 66, a: '6', sourate: 'At-Tahrim', fr: "Ô vous qui avez cru ! Préservez vos personnes et vos familles d'un Feu dont le combustible sera les hommes et les pierres…" },
  'furqan-70': { s: 25, a: '70', sourate: 'Al-Furqan', fr: "…sauf celui qui se repent, croit et accomplit une bonne œuvre : ceux-là, Allah changera leurs mauvaises actions en bonnes. Allah est Pardonneur et Miséricordieux." },
  'furqan-27': { s: 25, a: '27-29', sourate: 'Al-Furqan', fr: "Le jour où l'injuste se mordra les deux mains et dira : « Hélas pour moi ! Si seulement j'avais suivi le chemin avec le Messager ! Malheur à moi ! Si seulement je n'avais pas pris un tel pour ami ! Il m'a égaré loin du rappel après qu'il me soit parvenu. »" },
  'furqan-74': { s: 25, a: '74', sourate: 'Al-Furqan', ar: 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', fr: "« Seigneur, donne-nous, en nos épouses et nos descendants, la joie des yeux, et fais de nous un guide pour les pieux. »" },
  'hud-114': { s: 11, a: '114', sourate: 'Hud', ar: 'إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ', fr: "Accomplis la prière aux deux extrémités du jour et à certaines heures de la nuit. Les bonnes actions dissipent les mauvaises. Cela est une exhortation pour ceux qui réfléchissent." },
  'baqara-222': { s: 2, a: '222', sourate: 'Al-Baqara', ar: 'إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ', fr: "…Allah aime ceux qui se repentent et Il aime ceux qui se purifient." },
  'nisa-17': { s: 4, a: '17', sourate: "An-Nisa'", fr: "Allah accueille le repentir de ceux qui font le mal par ignorance et qui se repentent peu après…" },
  'nisa-110': { s: 4, a: '110', sourate: "An-Nisa'", fr: "Quiconque agit mal ou fait du tort à lui-même, puis implore le pardon d'Allah, trouvera Allah Pardonneur et Miséricordieux." },
  'nisa-31': { s: 4, a: '31', sourate: "An-Nisa'", fr: "Si vous évitez les grands péchés qui vous sont interdits, Nous effacerons vos méfaits de votre compte et Nous vous ferons entrer dans un lieu d'honneur." },
  'nisa-135': { s: 4, a: '135', sourate: "An-Nisa'", fr: "Ô vous qui avez cru ! Observez strictement la justice et soyez des témoins [véridiques] pour Allah, fût-ce contre vous-mêmes, contre vos père et mère ou vos proches…" },
  'nisa-28': { s: 4, a: '28', sourate: "An-Nisa'", fr: "Allah veut vous alléger [les obligations], car l'homme a été créé faible." },
  'ankabut-45': { s: 29, a: '45', sourate: "Al-'Ankabut", ar: 'إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنكَرِ', fr: "Récite ce qui t'est révélé du Livre et accomplis la prière. La prière préserve de la turpitude et du blâmable. Et le rappel d'Allah est ce qu'il y a de plus grand." },
  'ankabut-69': { s: 29, a: '69', sourate: "Al-'Ankabut", fr: "Et ceux qui luttent pour Notre cause, Nous les guiderons certes sur Nos sentiers. Allah est en vérité avec les bienfaisants." },
  'talaq-2': { s: 65, a: '2-3', sourate: 'At-Talaq', ar: 'وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا', fr: "…Et quiconque craint Allah, Il lui donnera une issue favorable, et lui accordera Ses dons par des moyens sur lesquels il ne comptait pas. Et quiconque place sa confiance en Allah, Il lui suffit." },
  'baqara-152': { s: 2, a: '152', sourate: 'Al-Baqara', ar: 'فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ', fr: "Souvenez-vous de Moi, Je Me souviendrai de vous. Soyez-Moi reconnaissants et ne soyez pas ingrats envers Moi." },
  'baqara-153': { s: 2, a: '153', sourate: 'Al-Baqara', ar: 'إِنَّ اللَّهَ مَعَ الصَّابِرِينَ', fr: "Ô vous qui avez cru ! Cherchez secours dans l'endurance et la prière. Allah est avec les endurants." },
  'baqara-286': { s: 2, a: '286', sourate: 'Al-Baqara', ar: 'لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا', fr: "Allah n'impose à aucune âme une charge supérieure à sa capacité…" },
  'baqara-201': { s: 2, a: '201', sourate: 'Al-Baqara', ar: 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', fr: "« Seigneur, accorde-nous une belle part ici-bas et une belle part dans l'au-delà, et protège-nous du châtiment du Feu. »" },
  'baqara-261': { s: 2, a: '261', sourate: 'Al-Baqara', fr: "Ceux qui dépensent leurs biens dans le sentier d'Allah ressemblent à un grain d'où naissent sept épis, chaque épi contenant cent grains. Allah multiplie la récompense à qui Il veut…" },
  'baqara-165': { s: 2, a: '165', sourate: 'Al-Baqara', fr: "…Mais ceux qui ont cru sont les plus ardents en l'amour d'Allah." },
  'kahf-28': { s: 18, a: '28', sourate: 'Al-Kahf', fr: "Fais preuve de patience [en restant] avec ceux qui invoquent leur Seigneur matin et soir, désirant Sa Face. Et que tes yeux ne se détachent pas d'eux, recherchant le faste de la vie d'ici-bas…" },
  'zukhruf-67': { s: 43, a: '67', sourate: 'Az-Zukhruf', fr: "Les amis intimes seront, ce jour-là, ennemis les uns des autres, excepté les pieux." },
  'muminun-1': { s: 23, a: '1-3', sourate: "Al-Mu'minun", fr: "Bienheureux sont les croyants, ceux qui sont humbles dans leur prière, et qui se détournent des futilités." },
  'muminun-99': { s: 23, a: '99-100', sourate: "Al-Mu'minun", fr: "Puis, lorsque la mort vient à l'un d'eux, il dit : « Seigneur ! Fais-moi revenir [sur terre], afin que je fasse du bien dans ce que je délaissais. » Non, c'est simplement une parole qu'il dit. Derrière eux, il y a une barrière (barzakh) jusqu'au jour où ils seront ressuscités." },
  'maida-8': { s: 5, a: '8', sourate: "Al-Ma'ida", fr: "…Et que la haine pour un peuple ne vous incite pas à être injustes. Pratiquez l'équité : cela est plus proche de la piété." },
  'anfal-27': { s: 8, a: '27', sourate: 'Al-Anfal', fr: "Ô vous qui avez cru ! Ne trahissez pas Allah et le Messager. Ne trahissez pas sciemment la confiance qu'on a placée en vous." },
  'anfal-2': { s: 8, a: '2', sourate: 'Al-Anfal', fr: "Les vrais croyants sont ceux dont les cœurs frémissent quand on mentionne Allah, et dont la foi augmente quand Ses versets leur sont récités, et qui placent leur confiance en leur Seigneur." },
  'humaza-1': { s: 104, a: '1', sourate: 'Al-Humaza', fr: "Malheur à tout calomniateur, diffamateur." },
  'takathur-1': { s: 102, a: '1-2', sourate: 'At-Takathur', fr: "La course aux richesses vous distrait, jusqu'à ce que vous visitiez les tombes." },
  'sajda-17': { s: 32, a: '17', sourate: 'As-Sajda', fr: "Aucune âme ne sait ce qu'on a réservé pour eux comme réjouissance pour les yeux, en récompense de ce qu'ils œuvraient." },
  'qaf-16': { s: 50, a: '16-18', sourate: 'Qaf', fr: "Nous avons effectivement créé l'homme et Nous savons ce que son âme lui suggère, et Nous sommes plus près de lui que sa veine jugulaire… Il ne prononce pas une parole sans avoir auprès de lui un observateur prêt à l'inscrire." },
  'munafiqun-9': { s: 63, a: '9', sourate: 'Al-Munafiqun', fr: "Ô vous qui avez cru ! Que ni vos biens ni vos enfants ne vous distraient du rappel d'Allah. Et quiconque fait cela, ceux-là sont les perdants." },
  'anam-120': { s: 6, a: '120', sourate: "Al-An'am", fr: "Laissez le péché apparent ou caché. Ceux qui acquièrent le péché seront rétribués selon ce qu'ils ont commis." },
  'najm-32': { s: 53, a: '32', sourate: 'An-Najm', fr: "Ceux qui évitent les grands péchés et les turpitudes, et ne commettent que des fautes légères… Ton Seigneur est immense dans Son pardon…" },
  'fussilat-34': { s: 41, a: '34', sourate: 'Fussilat', fr: "La bonne action et la mauvaise ne sont pas pareilles. Repousse [le mal] par ce qui est meilleur : alors celui avec qui tu avais une inimitié deviendra tel un ami chaleureux." },
  'tawba-119': { s: 9, a: '119', sourate: 'At-Tawba', fr: "Ô vous qui avez cru ! Craignez Allah et soyez avec les véridiques." },
  'saff-2': { s: 61, a: '2-3', sourate: 'As-Saff', fr: "Ô vous qui avez cru ! Pourquoi dites-vous ce que vous ne faites pas ? C'est une grande abomination auprès d'Allah que de dire ce que vous ne faites pas." },
  'nahl-90': { s: 16, a: '90', sourate: 'An-Nahl', fr: "Certes, Allah ordonne la justice, la bienfaisance et l'assistance aux proches. Et Il interdit la turpitude, l'acte répréhensible et la rébellion…" },
  'nisa-54': { s: 4, a: '54', sourate: "An-Nisa'", fr: "Envient-ils les gens pour ce qu'Allah leur a donné de Sa grâce ?…" },
  'falaq-5': { s: 113, a: '1-5', sourate: 'Al-Falaq', fr: "Dis : « Je cherche protection auprès du Seigneur de l'aube naissante, contre le mal des êtres qu'Il a créés, contre le mal de l'obscurité quand elle s'approfondit, contre le mal de celles qui soufflent sur les nœuds, et contre le mal de l'envieux quand il envie. »" },
  'nas-1': { s: 114, a: '1-6', sourate: 'An-Nas', fr: "Dis : « Je cherche protection auprès du Seigneur des hommes, le Souverain des hommes, Dieu des hommes, contre le mal du mauvais conseiller, furtif, qui souffle le mal dans les poitrines des hommes, qu'il soit un djinn ou un être humain. »" },
  'muzzammil-4': { s: 73, a: '4', sourate: 'Al-Muzzammil', fr: "…et récite le Coran lentement et clairement (tartil)." },
  'muhammad-24': { s: 47, a: '24', sourate: 'Muhammad', fr: "Ne méditent-ils donc pas sur le Coran ? Ou y a-t-il des cadenas sur leurs cœurs ?" },
  'taghabun-16': { s: 64, a: '16', sourate: 'At-Taghabun', fr: "Craignez Allah donc, autant que vous pouvez, écoutez, obéissez et faites des dépenses [dans le bien]…" },
  'anbiya-87': { s: 21, a: '87', sourate: "Al-Anbiya'", ar: 'لَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ', fr: "…« Pas de divinité à part Toi ! Gloire à Toi ! J'ai été vraiment du nombre des injustes. »" },
  'imran-173': { s: 3, a: '173', sourate: "Al 'Imran", ar: 'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', fr: "…« Allah nous suffit ; Il est notre meilleur garant. »" },
}

export const HADITHS = {
  intention: { fr: "Les actions ne valent que par les intentions, et chacun n'aura que ce qu'il a eu l'intention de faire…", ar: 'إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ', ref: 'Al-Bukhari n°1 ; Muslim n°1907', grade: 'Sahih (unanimement authentique)', contexte: "Rapporté par 'Umar ibn al-Khattab. Les savants le considèrent comme l'un des fondements de la religion : la valeur d'un acte dépend de l'intention qui l'anime." },
  repentants: { fr: "Tout fils d'Adam commet des fautes, et les meilleurs de ceux qui commettent des fautes sont ceux qui se repentent.", ref: "At-Tirmidhi n°2499 ; Ibn Majah n°4251", grade: 'Hasan', contexte: "Rapporté par Anas ibn Malik. Il rappelle que l'erreur fait partie de la nature humaine ; ce qui distingue le croyant, c'est son retour vers Allah." },
  'point-noir': { fr: "Lorsque le croyant commet un péché, un point noir se forme sur son cœur. S'il se repent, cesse et demande pardon, son cœur est purifié. Mais s'il continue, [le noir] augmente jusqu'à recouvrir son cœur. C'est cela le « ran » qu'Allah a mentionné : « Pas du tout ! Mais ce qu'ils ont accompli a couvert leurs cœurs. »", ref: "At-Tirmidhi n°3334 ; Ibn Majah n°4244", grade: 'Hasan sahih (selon at-Tirmidhi)', contexte: "Rapporté par Abu Hurayra. Ce hadith explique le verset 14 de la sourate Al-Mutaffifin et décrit comment la répétition des péchés affecte progressivement le cœur." },
  'morceau-chair': { fr: "…Certes, il y a dans le corps un morceau de chair : s'il est sain, tout le corps est sain, et s'il est corrompu, tout le corps est corrompu. Certes, c'est le cœur.", ref: 'Al-Bukhari n°52 ; Muslim n°1599', grade: 'Sahih', contexte: "Rapporté par an-Nu'man ibn Bashir, à la fin du hadith sur le licite et l'illicite et les choses douteuses." },
  'regard-ali': { fr: "Ô 'Ali, ne fais pas suivre un regard par un autre regard : le premier t'est pardonné, mais pas le second.", ref: "Abu Dawud n°2149 ; At-Tirmidhi n°2777", grade: 'Hasan', contexte: "Conseil du Prophète ﷺ à 'Ali ibn Abi Talib. Le premier regard involontaire n'est pas reproché ; c'est le fait de le prolonger volontairement qui l'est." },
  'zina-yeux': { fr: "Allah a prescrit au fils d'Adam sa part de zina qu'il atteindra inévitablement : la zina des yeux est le regard, la zina de la langue est la parole ; l'âme souhaite et désire, et le sexe confirme cela ou le dément.", ref: 'Al-Bukhari n°6243 ; Muslim n°2657', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Les savants expliquent que le regard, la parole et le désir sont des « portes » qui mènent à la fornication ; d'où l'importance de les fermer." },
  'bien-ou-silence': { fr: "Que celui qui croit en Allah et au Jour dernier dise du bien ou qu'il se taise.", ref: 'Al-Bukhari n°6018 ; Muslim n°47', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra, dans un hadith regroupant plusieurs règles de comportement (honorer le voisin, l'invité…)." },
  medisance: { fr: "« Savez-vous ce qu'est la médisance ? » Ils dirent : « Allah et Son Messager savent mieux. » Il dit : « C'est que tu mentionnes ton frère par ce qu'il déteste. » On lui dit : « Et si ce que je dis se trouve réellement en lui ? » Il dit : « Si cela se trouve en lui, tu as médit de lui, et si cela ne se trouve pas en lui, tu l'as calomnié. »", ref: 'Muslim n°2589', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Il donne la définition précise de la médisance (ghiba) et de la calomnie (buhtan)." },
  verite: { fr: "Attachez-vous à la véracité, car la véracité guide vers la piété et la piété guide vers le Paradis… Et gardez-vous du mensonge, car le mensonge guide vers la perversité et la perversité guide vers le Feu…", ref: 'Al-Bukhari n°6094 ; Muslim n°2607', grade: 'Sahih', contexte: "Rapporté par 'Abd Allah ibn Mas'ud. Il montre que chaque habitude, bonne ou mauvaise, entraîne la suivante." },
  orgueil: { fr: "N'entrera pas au Paradis celui qui a dans son cœur le poids d'un atome d'orgueil. » Un homme dit : « On aime avoir de beaux vêtements et de belles chaussures. » Il dit : « Allah est Beau et Il aime la beauté. L'orgueil, c'est rejeter la vérité et mépriser les gens. »", ref: 'Muslim n°91', grade: 'Sahih', contexte: "Rapporté par 'Abd Allah ibn Mas'ud. Il précise que l'orgueil n'est pas le soin de son apparence, mais le refus de la vérité et le mépris d'autrui." },
  'pas-envie': { fr: "Ne vous enviez pas, ne faites pas monter les prix les uns contre les autres, ne vous haïssez pas, ne vous tournez pas le dos… Soyez, ô serviteurs d'Allah, des frères. Le musulman est le frère du musulman : il ne lui fait pas de tort, ne l'abandonne pas et ne le méprise pas… Il suffit comme mal pour une personne qu'elle méprise son frère musulman.", ref: 'Muslim n°2564', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. C'est l'un des hadiths les plus complets sur la fraternité et les maladies du cœur." },
  'coeurs-actions': { fr: "Allah ne regarde ni vos corps ni vos apparences, mais Il regarde vos cœurs et vos actions.", ref: 'Muslim n°2564', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra, dans le même hadith que le précédent. Il rappelle que la valeur véritable est intérieure." },
  'fort-colere': { fr: "Le fort n'est pas celui qui terrasse les gens, mais le fort est celui qui se maîtrise lors de la colère.", ref: 'Al-Bukhari n°6114 ; Muslim n°2609', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Il redéfinit la force comme une maîtrise de soi." },
  'pas-colere': { fr: "Un homme dit au Prophète ﷺ : « Conseille-moi. » Il dit : « Ne te mets pas en colère. » L'homme répéta plusieurs fois, et il lui répondait : « Ne te mets pas en colère. »", ar: 'لَا تَغْضَبْ', ref: 'Al-Bukhari n°6116', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Les savants expliquent que la colère est la clé de nombreux maux ; s'en préserver protège de beaucoup de péchés." },
  'refuge-colere': { fr: "Deux hommes se disputaient près du Prophète ﷺ ; l'un d'eux était rouge de colère. Le Prophète ﷺ dit : « Je connais une parole qui, s'il la disait, lui ôterait ce qu'il ressent : « Je cherche refuge auprès d'Allah contre Shaytan. »", ref: 'Al-Bukhari n°6115 ; Muslim n°2610', grade: 'Sahih', contexte: "Rapporté par Sulayman ibn Surad. Un remède concret enseigné face à la colère." },
  pudeur: { fr: "La foi comporte soixante et quelques branches, et la pudeur (al-haya') est une branche de la foi.", ar: 'وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ', ref: 'Al-Bukhari n°9 ; Muslim n°35', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. La pudeur est présentée comme un élément de la foi elle-même." },
  'pudeur-bien': { fr: "La pudeur n'apporte que du bien.", ref: 'Al-Bukhari n°6117 ; Muslim n°37', grade: 'Sahih', contexte: "Rapporté par 'Imran ibn Husayn." },
  'religion-ami': { fr: "L'homme suit la religion de son ami intime ; que chacun de vous regarde donc qui il prend pour ami intime.", ref: "Abu Dawud n°4833 ; At-Tirmidhi n°2378", grade: 'Hasan', contexte: "Rapporté par Abu Hurayra. Il souligne l'influence profonde des fréquentations sur la pratique religieuse." },
  'musc-forgeron': { fr: "Le bon et le mauvais compagnon sont comme le vendeur de musc et le forgeron : le vendeur de musc, soit il t'en offre, soit tu lui en achètes, soit tu sens auprès de lui une bonne odeur ; quant au forgeron, soit il brûle tes vêtements, soit tu sens auprès de lui une odeur désagréable.", ref: 'Al-Bukhari n°2101 ; Muslim n°2628', grade: 'Sahih', contexte: "Rapporté par Abu Musa al-Ash'ari. Une parabole célèbre sur l'influence de l'entourage." },
  'deux-bienfaits': { fr: "Il est deux bienfaits dont beaucoup de gens sont lésés : la santé et le temps libre.", ref: 'Al-Bukhari n°6412', grade: 'Sahih', contexte: "Rapporté par Ibn 'Abbas. Il invite à ne pas gaspiller le temps, qui est un capital." },
  'delaisser-inutile': { fr: "Fait partie du bon islam d'une personne le fait de délaisser ce qui ne la concerne pas.", ref: "At-Tirmidhi n°2317 ; Ibn Majah n°3976", grade: 'Hasan (cité par an-Nawawi dans les 40 hadiths, n°12)', contexte: "Rapporté par Abu Hurayra. Un principe essentiel face aux distractions et à la curiosité inutile." },
  'main-tendue': { fr: "Allah tend Sa main la nuit pour que se repente celui qui a mal agi le jour, et Il tend Sa main le jour pour que se repente celui qui a mal agi la nuit, jusqu'à ce que le soleil se lève de son couchant.", ref: 'Muslim n°2759', grade: 'Sahih', contexte: "Rapporté par Abu Musa al-Ash'ari. La porte du repentir reste ouverte à tout moment." },
  'joie-repentir': { fr: "Allah se réjouit davantage du repentir de Son serviteur que l'un de vous qui retrouve sa monture après l'avoir perdue dans un désert.", ref: 'Al-Bukhari n°6309 ; Muslim n°2747', grade: 'Sahih', contexte: "Rapporté par Anas ibn Malik. Il montre l'amour d'Allah pour celui qui revient vers Lui." },
  'soixante-dix': { fr: "Par Allah, je demande pardon à Allah et je me repens à Lui plus de soixante-dix fois par jour.", ref: 'Al-Bukhari n°6307', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Le Prophète ﷺ, pourtant pardonné, montrait l'exemple d'un istighfar constant." },
  agonie: { fr: "Allah accepte le repentir du serviteur tant qu'il n'est pas à l'agonie.", ref: 'At-Tirmidhi n°3537 ; Ibn Majah n°4253', grade: 'Hasan', contexte: "Rapporté par Ibn 'Umar. Il invite à ne pas reporter son repentir, car nul ne connaît l'heure de sa mort." },
  regret: { fr: "Le regret est un repentir.", ar: 'النَّدَمُ تَوْبَةٌ', ref: 'Ibn Majah n°4252 ; Ahmad n°3568', grade: 'Sahih (authentifié par al-Albani)', contexte: "Rapporté par 'Abd Allah ibn Mas'ud. Le regret sincère est le cœur même de la tawbah." },
  'comme-sans-peche': { fr: "Celui qui se repent d'un péché est comme celui qui n'a pas de péché.", ref: 'Ibn Majah n°4250', grade: 'Hasan (selon al-Albani)', contexte: "Rapporté par 'Abd Allah ibn Mas'ud. Un message d'espoir pour celui qui revient sincèrement." },
  'nuages-ciel': { fr: "Allah le Très-Haut a dit : « Ô fils d'Adam ! Tant que tu M'invoques et que tu espères en Moi, Je te pardonne ce qui vient de toi, sans M'en soucier. Ô fils d'Adam ! Si tes péchés atteignaient les nuages du ciel, puis que tu Me demandais pardon, Je te pardonnerais… »", ref: 'At-Tirmidhi n°3540', grade: 'Hasan (selon at-Tirmidhi)', contexte: "Hadith qudsi rapporté par Anas ibn Malik (n°42 des 40 hadiths d'an-Nawawi)." },
  'entoure-desirs': { fr: "Le Paradis est entouré de choses désagréables, et l'Enfer est entouré de désirs.", ref: 'Muslim n°2822 (et Al-Bukhari n°6487 avec « voilé »)', grade: 'Sahih', contexte: "Rapporté par Anas ibn Malik et Abu Hurayra. Le chemin du bien demande des efforts, tandis que le mal se présente souvent sous une forme attirante." },
  'crains-allah': { fr: "Crains Allah où que tu sois, fais suivre la mauvaise action par une bonne qui l'effacera, et comporte-toi avec les gens d'un bon comportement.", ref: 'At-Tirmidhi n°1987', grade: 'Hasan', contexte: "Conseil du Prophète ﷺ à Abu Dharr et Mu'adh ibn Jabal (n°18 des 40 hadiths d'an-Nawawi)." },
  regularite: { fr: "Les actions les plus aimées d'Allah sont les plus régulières, même si elles sont peu nombreuses.", ref: 'Al-Bukhari n°6464 ; Muslim n°783', grade: 'Sahih', contexte: "Rapporté par 'A'icha. Un principe clé pour installer de bonnes habitudes durables." },
  'grands-peches': { fr: "« Voulez-vous que je vous informe du plus grand des grands péchés ? » … « Associer quelque chose à Allah et la désobéissance envers les parents. » Il était accoudé, puis il s'assit et dit : « Et la parole mensongère, et le faux témoignage. »", ref: 'Al-Bukhari n°5976 ; Muslim n°87', grade: 'Sahih', contexte: "Rapporté par Abu Bakra. La désobéissance aux parents est citée juste après l'association." },
  'mere-trois': { fr: "Un homme demanda : « Ô Messager d'Allah, qui a le plus droit à ma bonne compagnie ? » Il dit : « Ta mère. » — « Puis qui ? » — « Ta mère. » — « Puis qui ? » — « Ta mère. » — « Puis qui ? » — « Ton père. »", ref: 'Al-Bukhari n°5971 ; Muslim n°2548', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra." },
  'musulman-langue': { fr: "Le musulman est celui dont les musulmans sont à l'abri de sa langue et de sa main.", ref: 'Al-Bukhari n°10 ; Muslim n°40', grade: 'Sahih', contexte: "Rapporté par 'Abd Allah ibn 'Amr." },
  sourire: { fr: "Ne méprise aucune bonne action, ne serait-ce que de rencontrer ton frère avec un visage souriant.", ref: 'Muslim n°2626', grade: 'Sahih', contexte: "Rapporté par Abu Dharr. Aucun bien n'est trop petit." },
  'abandon-priere': { fr: "Entre l'homme et l'association et la mécréance, il y a l'abandon de la prière.", ref: 'Muslim n°82', grade: 'Sahih', contexte: "Rapporté par Jabir ibn 'Abd Allah. Il montre la gravité de l'abandon de la prière ; les savants ont des avis détaillés sur le statut de celui qui la délaisse par négligence." },
  riviere: { fr: "« Si une rivière coulait devant la porte de l'un de vous et qu'il s'y lavait cinq fois par jour, lui resterait-il de la saleté ? » Ils dirent : « Il ne lui en resterait rien. » Il dit : « Il en est de même des cinq prières : Allah efface par elles les péchés. »", ref: 'Al-Bukhari n°528 ; Muslim n°667', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra." },
  'priere-heure': { fr: "« Quelle est l'œuvre la plus aimée d'Allah ? » Il dit : « La prière accomplie à son heure. » — « Puis laquelle ? » — « La bonté envers les parents. » — « Puis laquelle ? » — « Le combat dans le sentier d'Allah. »", ref: 'Al-Bukhari n°527 ; Muslim n°85', grade: 'Sahih', contexte: "Rapporté par 'Abd Allah ibn Mas'ud." },
  'vivant-mort': { fr: "L'exemple de celui qui évoque son Seigneur et de celui qui ne L'évoque pas est comme l'exemple du vivant et du mort.", ref: 'Al-Bukhari n°6407', grade: 'Sahih', contexte: "Rapporté par Abu Musa al-Ash'ari. Le dhikr est la vie du cœur." },
  'deux-paroles': { fr: "Deux paroles légères sur la langue, lourdes dans la balance, aimées du Tout Miséricordieux : « Subhana Allahi wa bihamdihi, Subhana Allahi l-'Azim. »", ref: 'Al-Bukhari n°6406 ; Muslim n°2694', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. C'est le dernier hadith du Sahih d'al-Bukhari." },
  'meilleur-coran': { fr: "Le meilleur d'entre vous est celui qui apprend le Coran et l'enseigne.", ref: 'Al-Bukhari n°5027', grade: 'Sahih', contexte: "Rapporté par 'Uthman ibn 'Affan." },
  'sadaqa-diminue': { fr: "L'aumône ne diminue en rien les biens. Allah n'augmente le serviteur qui pardonne qu'en honneur, et nul ne s'humilie pour Allah sans qu'Allah ne l'élève.", ref: 'Muslim n°2588', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Il réunit la sadaqa, le pardon et l'humilité." },
  'sang-shaytan': { fr: "Shaytan circule dans le fils d'Adam comme circule le sang.", ref: 'Al-Bukhari n°2038 ; Muslim n°2175', grade: 'Sahih', contexte: "Rapporté par Safiyya. Le Prophète ﷺ l'a dit pour éviter que des gens aient de mauvaises pensées : il faut se méfier des suggestions de Shaytan." },
  'pense-pardonne': { fr: "Allah a pardonné à ma communauté ce que leurs âmes se murmurent, tant qu'ils ne le mettent pas en acte ou ne le disent pas.", ref: 'Al-Bukhari n°5269 ; Muslim n°127', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Un réconfort pour ceux qui souffrent de waswas : les pensées non voulues ne sont pas comptées comme péchés." },
  'qui-a-cree': { fr: "Shaytan vient à l'un de vous et dit : « Qui a créé ceci ? Qui a créé cela ? » jusqu'à dire : « Qui a créé ton Seigneur ? » Lorsqu'il en arrive là, qu'il cherche refuge auprès d'Allah et qu'il cesse.", ref: 'Al-Bukhari n°3276 ; Muslim n°134', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Le remède prophétique aux waswas : chercher refuge en Allah et ne pas s'y attarder." },
  'destructeur-plaisirs': { fr: "Évoquez souvent le destructeur des plaisirs : la mort.", ref: 'At-Tirmidhi n°2307 ; Ibn Majah n°4258', grade: 'Hasan sahih (selon at-Tirmidhi)', contexte: "Rapporté par Abu Hurayra. Se rappeler la mort aide à relativiser les plaisirs passagers." },
  'premiere-etape': { fr: "La tombe est la première des étapes de l'au-delà : celui qui en est sauvé, ce qui vient après sera plus facile ; et celui qui n'en est pas sauvé, ce qui vient après sera plus dur.", ref: 'At-Tirmidhi n°2308 ; Ibn Majah n°4267', grade: 'Hasan', contexte: "Rapporté par 'Uthman ibn 'Affan, qui pleurait lorsqu'il se tenait devant une tombe." },
  'pieds-bougeront': { fr: "Les pieds du serviteur ne bougeront pas le Jour de la Résurrection avant qu'il ne soit interrogé sur sa vie et ce qu'il en a fait, sur sa science et ce qu'il en a fait, sur ses biens — d'où il les a acquis et comment il les a dépensés — et sur son corps et ce qu'il en a usé.", ref: 'At-Tirmidhi n°2417', grade: 'Hasan sahih (selon at-Tirmidhi)', contexte: "Rapporté par Abu Barza al-Aslami. Il résume la responsabilité de chaque personne devant Allah." },
  'cent-parts': { fr: "Allah a fait la miséricorde en cent parts. Il en a gardé auprès de Lui quatre-vingt-dix-neuf et en a fait descendre sur terre une seule part. C'est par cette part que les créatures se font miséricorde…", ref: 'Al-Bukhari n°6000 ; Muslim n°2752', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Il donne une idée de l'immensité de la miséricorde divine." },
  'misericorde-devance': { fr: "Lorsqu'Allah créa la création, Il écrivit dans un Livre qui est auprès de Lui, au-dessus du Trône : « Ma miséricorde devance Ma colère. »", ref: 'Al-Bukhari n°7404 ; Muslim n°2751', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra." },
  'jeunes-mariage': { fr: "Ô assemblée de jeunes gens ! Que celui d'entre vous qui en a les moyens se marie, car cela aide davantage à baisser le regard et à préserver la chasteté. Et celui qui ne le peut pas, qu'il jeûne, car ce sera pour lui une protection.", ref: 'Al-Bukhari n°5066 ; Muslim n°1400', grade: 'Sahih', contexte: "Rapporté par 'Abd Allah ibn Mas'ud. Une solution prophétique concrète face au désir." },
  'troisieme-shaytan': { fr: "Un homme ne s'isole pas avec une femme sans que Shaytan ne soit leur troisième.", ref: 'At-Tirmidhi n°2165', grade: 'Sahih (selon at-Tirmidhi : hasan sahih gharib)', contexte: "Rapporté par 'Umar ibn al-Khattab. Il interdit l'isolement (khalwa) entre un homme et une femme qui ne sont pas mahram." },
  'fitna-femmes': { fr: "Je n'ai pas laissé après moi d'épreuve plus nuisible pour les hommes que les femmes.", ref: 'Al-Bukhari n°5096 ; Muslim n°2740', grade: 'Sahih', contexte: "Rapporté par Usama ibn Zayd. Les savants expliquent qu'il s'agit d'un avertissement sur la force de l'attirance et non d'un mépris envers les femmes ; l'islam honore la femme et appelle les deux sexes à la pudeur." },
  'vetues-nues': { fr: "Il y a deux catégories parmi les gens du Feu que je n'ai pas vues : … des femmes vêtues mais nues, qui se pavanent et attirent [les regards]… Elles n'entreront pas au Paradis et n'en sentiront pas le parfum…", ref: 'Muslim n°2128', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Les savants expliquent « vêtues mais nues » par des vêtements transparents, moulants ou qui découvrent. C'est un avertissement général sur un comportement, non un jugement sur une personne précise." },
  'or-soie': { fr: "La soie et l'or ont été rendus licites pour les femmes de ma communauté et interdits pour ses hommes.", ref: "At-Tirmidhi n°1720 ; An-Nasa'i n°5148", grade: 'Sahih', contexte: "Rapporté par Abu Musa al-Ash'ari. Une des prescriptions vestimentaires propres aux hommes." },
  'etranger-voyageur': { fr: "Sois dans ce monde comme si tu étais un étranger ou un voyageur de passage.", ref: 'Al-Bukhari n°6416', grade: 'Sahih', contexte: "Conseil du Prophète ﷺ à 'Abd Allah ibn 'Umar." },
  'deux-vallees': { fr: "Si le fils d'Adam possédait deux vallées d'or, il en voudrait une troisième. Rien ne remplit le ventre du fils d'Adam si ce n'est la terre [de la tombe]. Et Allah accepte le repentir de celui qui se repent.", ref: 'Al-Bukhari n°6436 ; Muslim n°1048', grade: 'Sahih', contexte: "Rapporté par Ibn 'Abbas et Anas. Sur l'avidité et l'attachement au bas monde." },
  'laisse-pour-allah': { fr: "Tu ne laisseras jamais une chose par crainte d'Allah sans qu'Allah ne te donne mieux qu'elle.", ref: 'Musnad Ahmad (5/363)', grade: 'Sahih (selon Shu\'ayb al-Arna\'ut et al-Albani)', contexte: "Rapporté par un compagnon bédouin. Un grand encouragement pour celui qui abandonne une habitude interdite." },
  'cinq-avant-cinq': { fr: "Profite de cinq choses avant cinq autres : ta jeunesse avant ta vieillesse, ta santé avant ta maladie, ta richesse avant ta pauvreté, ton temps libre avant tes occupations, et ta vie avant ta mort.", ref: 'Al-Hakim, Al-Mustadrak n°7846', grade: 'Sahih (authentifié par al-Albani)', contexte: "Rapporté par Ibn 'Abbas. Un remède à la procrastination religieuse." },
  'remercier-gens': { fr: "Celui qui ne remercie pas les gens ne remercie pas Allah.", ref: 'Abu Dawud n°4811 ; At-Tirmidhi n°1954', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra." },
  'croyant-etonnant': { fr: "Étonnante est l'affaire du croyant ! Tout ce qui lui arrive est un bien pour lui, et cela n'est donné qu'au croyant : s'il lui arrive une chose heureuse, il remercie, et c'est un bien pour lui ; s'il lui arrive un malheur, il patiente, et c'est un bien pour lui.", ref: 'Muslim n°2999', grade: 'Sahih', contexte: "Rapporté par Suhayb. Il réunit la gratitude et la patience." },
  injustice: { fr: "L'injustice sera des ténèbres le Jour de la Résurrection.", ref: 'Al-Bukhari n°2447 ; Muslim n°2579', grade: 'Sahih', contexte: "Rapporté par 'Abd Allah ibn 'Umar." },
  hypocrite: { fr: "Les signes de l'hypocrite sont trois : lorsqu'il parle, il ment ; lorsqu'il promet, il ne tient pas sa promesse ; et lorsqu'on lui confie quelque chose, il trahit.", ref: 'Al-Bukhari n°33 ; Muslim n°59', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Les savants précisent qu'il s'agit de traits de comportement hypocrite dont le croyant doit se préserver." },
  insulte: { fr: "Insulter le musulman est une perversité, et le combattre est de la mécréance.", ref: 'Al-Bukhari n°48 ; Muslim n°64', grade: 'Sahih', contexte: "Rapporté par 'Abd Allah ibn Mas'ud." },
  'pas-croyant-grossier': { fr: "Le croyant n'est pas celui qui dénigre, qui maudit, qui est grossier ou obscène.", ref: 'At-Tirmidhi n°1977', grade: 'Hasan', contexte: "Rapporté par 'Abd Allah ibn Mas'ud." },
  ostentation: { fr: "Ce que je crains le plus pour vous, c'est le petit shirk. » On demanda : « Qu'est-ce que le petit shirk ? » Il dit : « L'ostentation (ar-riya'). »", ref: 'Ahmad n°23630', grade: 'Hasan / sahih selon plusieurs savants (dont al-Albani)', contexte: "Rapporté par Mahmud ibn Labid. Il concerne le fait d'agir pour être vu et admiré des gens — un danger accru à l'ère des réseaux sociaux." },
  'aimer-frere': { fr: "Aucun de vous n'est [vraiment] croyant tant qu'il n'aime pas pour son frère ce qu'il aime pour lui-même.", ref: 'Al-Bukhari n°13 ; Muslim n°45', grade: 'Sahih', contexte: "Rapporté par Anas ibn Malik. Le remède direct à la jalousie." },
  'garantie-paradis': { fr: "Celui qui me garantit [la préservation de] ce qui est entre ses deux mâchoires et ce qui est entre ses deux jambes, je lui garantis le Paradis.", ref: 'Al-Bukhari n°6474', grade: 'Sahih', contexte: "Rapporté par Sahl ibn Sa'd. La langue et la chasteté : deux portes majeures." },
  'balance-caractere': { fr: "Rien n'est plus lourd dans la balance du croyant, le Jour de la Résurrection, qu'un bon caractère.", ref: 'At-Tirmidhi n°2002 ; Abu Dawud n°4799', grade: 'Sahih', contexte: "Rapporté par Abu ad-Darda'." },
  'peches-meprises': { fr: "Prenez garde aux péchés que l'on considère comme insignifiants, car ils s'accumulent sur l'homme jusqu'à le détruire.", ref: 'Ahmad n°3818', grade: 'Sahih (selon al-Albani, Sahih al-Jami\' n°2686)', contexte: "Rapporté par 'Abd Allah ibn Mas'ud. Le Prophète ﷺ l'a illustré par des gens qui ramassent chacun un petit bâton jusqu'à pouvoir allumer un grand feu." },
  'plus-fin-cheveu': { fr: "Vous commettez des actes qui sont à vos yeux plus fins qu'un cheveu, alors que nous les comptions, à l'époque du Prophète ﷺ, parmi les choses qui mènent à la perdition.", ref: 'Al-Bukhari n°6492', grade: 'Sahih (parole du compagnon Anas ibn Malik)', contexte: "Il s'agit d'une parole d'Anas ibn Malik adressée à la génération suivante, et non d'une parole du Prophète ﷺ. Elle décrit exactement le phénomène de banalisation." },
  montagne: { fr: "Le croyant voit ses péchés comme s'il était assis au pied d'une montagne dont il craint qu'elle ne tombe sur lui, tandis que le pervers voit ses péchés comme une mouche passée sur son nez, qu'il chasse ainsi [d'un geste].", ref: 'Al-Bukhari n°6308', grade: 'Sahih (parole du compagnon Ibn Mas\'ud)', contexte: "Parole de 'Abd Allah ibn Mas'ud rapportée par al-Bukhari, dans le chapitre du repentir." },
  'mujahirin': { fr: "Toute ma communauté sera pardonnée, sauf ceux qui exposent publiquement [leurs péchés]. Fait partie de cela qu'un homme commette un acte la nuit, puis, alors qu'Allah l'a couvert, il dit au matin : « Ô untel, j'ai fait hier ceci et cela. »", ref: 'Al-Bukhari n°6069 ; Muslim n°2990', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra. Très actuel à l'ère des stories et publications : ne pas exposer ses péchés." },
  'peche-trouble': { fr: "La piété est le bon caractère, et le péché est ce qui trouble ton âme et que tu détestes que les gens découvrent.", ref: 'Muslim n°2553', grade: 'Sahih', contexte: "Rapporté par an-Nawwas ibn Sam'an. Un critère intérieur pour reconnaître le péché." },
  'laisse-doute': { fr: "Laisse ce qui te fait douter pour ce qui ne te fait pas douter.", ref: "At-Tirmidhi n°2518 ; An-Nasa'i n°5711", grade: 'Sahih', contexte: "Rapporté par al-Hasan ibn 'Ali (n°11 des 40 hadiths d'an-Nawawi)." },
  'rapprocher-nawafil': { fr: "Allah a dit : « …Mon serviteur ne cesse de se rapprocher de Moi par les œuvres surérogatoires jusqu'à ce que Je l'aime… »", ref: 'Al-Bukhari n°6502', grade: 'Sahih', contexte: "Hadith qudsi rapporté par Abu Hurayra. Le chemin de l'amour d'Allah passe par les obligations puis les actes surérogatoires." },
  'tasbih-priere': { fr: "Celui qui, après chaque prière, glorifie Allah 33 fois (Subhan Allah), Le loue 33 fois (Al-hamdu lillah) et proclame Sa grandeur 33 fois (Allahu akbar) — cela fait 99 — puis complète la centaine par : « La ilaha illa Allah wahdahu la sharika lah, lahu l-mulku wa lahu l-hamd, wa huwa 'ala kulli shay'in qadir », ses péchés lui sont pardonnés, fussent-ils comme l'écume de la mer.", ref: 'Muslim n°597', grade: 'Sahih', contexte: "Rapporté par Abu Hurayra." },
  'meilleur-dhikr': { fr: "Le meilleur rappel est « La ilaha illa Allah », et la meilleure invocation est « Al-hamdu lillah ».", ref: 'At-Tirmidhi n°3383 ; Ibn Majah n°3800', grade: 'Hasan', contexte: "Rapporté par Jabir ibn 'Abd Allah." },
  'sayyid-istighfar': { fr: "Le maître des demandes de pardon (Sayyid al-istighfar) est que tu dises : « Allahumma anta rabbi… ». Celui qui la dit le jour avec conviction et meurt ce jour-là avant le soir fait partie des gens du Paradis, et celui qui la dit la nuit avec conviction et meurt avant le matin fait partie des gens du Paradis.", ref: 'Al-Bukhari n°6306', grade: 'Sahih', contexte: "Rapporté par Shaddad ibn Aws." },
}

export const INVOCATIONS = {
  'sayyid-istighfar': { titre: "Sayyid al-istighfar (le maître du repentir)", theme: 'Repentir', ar: 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', tr: "Allāhumma anta rabbī, lā ilāha illā anta, khalaqtanī wa anā ʿabduka, wa anā ʿalā ʿahdika wa waʿdika mā staṭaʿtu, aʿūdhu bika min sharri mā ṣanaʿtu, abū'u laka bi-niʿmatika ʿalayya, wa abū'u laka bi-dhanbī, fa-ghfir lī fa-innahu lā yaghfiru dh-dhunūba illā anta.", fr: "Ô Allah, Tu es mon Seigneur, il n'y a de divinité que Toi. Tu m'as créé et je suis Ton serviteur. Je respecte mon engagement et ma promesse envers Toi autant que je le peux. Je cherche refuge auprès de Toi contre le mal que j'ai commis. Je reconnais Tes bienfaits envers moi et je reconnais mon péché. Pardonne-moi donc, car nul ne pardonne les péchés en dehors de Toi.", ref: 'Al-Bukhari n°6306' },
  'astaghfirullah': { titre: 'Demander pardon', theme: 'Repentir', ar: 'أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ', tr: "Astaghfiru Llāha wa atūbu ilayh.", fr: "Je demande pardon à Allah et je me repens à Lui.", ref: 'Al-Bukhari n°6307 (formule employée par le Prophète ﷺ)' },
  'adam': { titre: "L'invocation d'Adam et Hawwa", theme: 'Repentir', ar: 'رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', tr: "Rabbanā ẓalamnā anfusanā wa in lam taghfir lanā wa tarḥamnā la-nakūnanna mina l-khāsirīn.", fr: "Notre Seigneur, nous avons fait du tort à nous-mêmes. Si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants.", ref: "Coran, Al-A'raf 7:23" },
  'yunus': { titre: "L'invocation de Yunus (Jonas)", theme: 'Détresse', ar: 'لَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ', tr: "Lā ilāha illā anta, subḥānaka, innī kuntu mina ẓ-ẓālimīn.", fr: "Pas de divinité à part Toi ! Gloire à Toi ! J'ai été vraiment du nombre des injustes.", ref: "Coran, Al-Anbiya' 21:87 ; voir aussi At-Tirmidhi n°3505" },
  'coeur-ferme': { titre: 'Pour la fermeté du cœur', theme: 'Cœur', ar: 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', tr: "Yā muqalliba l-qulūb, thabbit qalbī ʿalā dīnik.", fr: "Ô Toi qui retournes les cœurs, affermis mon cœur sur Ta religion.", ref: 'At-Tirmidhi n°2140 (hasan)' },
  'ne-pas-devier': { titre: 'Pour ne pas dévier après la guidée', theme: 'Cœur', ar: 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً ۚ إِنَّكَ أَنتَ الْوَهَّابُ', tr: "Rabbanā lā tuzigh qulūbanā baʿda idh hadaytanā wa hab lanā min ladunka raḥmah, innaka anta l-wahhāb.", fr: "Seigneur, ne laisse pas dévier nos cœurs après que Tu nous as guidés, et accorde-nous Ta miséricorde. C'est Toi le Grand Donateur.", ref: "Coran, Al 'Imran 3:8" },
  'huda-afaf': { titre: 'Guidée, piété et chasteté', theme: 'Chasteté', ar: 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى', tr: "Allāhumma innī as'aluka l-hudā wa t-tuqā wa l-ʿafāfa wa l-ghinā.", fr: "Ô Allah, je Te demande la guidée, la piété, la chasteté et la suffisance.", ref: 'Muslim n°2721' },
  'sens': { titre: 'Protection du regard, de la langue et du cœur', theme: 'Chasteté', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّي', tr: "Allāhumma innī aʿūdhu bika min sharri samʿī, wa min sharri baṣarī, wa min sharri lisānī, wa min sharri qalbī, wa min sharri maniyyī.", fr: "Ô Allah, je cherche refuge auprès de Toi contre le mal de mon ouïe, le mal de ma vue, le mal de ma langue, le mal de mon cœur et le mal de mon désir.", ref: "Abu Dawud n°1551 ; At-Tirmidhi n°3492 (sahih)" },
  'akhlaq': { titre: 'Pour un bon caractère', theme: 'Comportement', ar: 'اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ', tr: "Allāhumma hdinī li-aḥsani l-akhlāq, lā yahdī li-aḥsanihā illā anta, wa ṣrif ʿannī sayyi'ahā, lā yaṣrifu ʿannī sayyi'ahā illā anta.", fr: "Ô Allah, guide-moi vers le meilleur comportement, nul ne guide vers le meilleur sinon Toi ; et écarte de moi le mauvais comportement, nul ne l'écarte de moi sinon Toi.", ref: 'Muslim n°771' },
  'dhikr-shukr': { titre: 'Pour le rappel et la gratitude', theme: 'Dhikr', ar: 'اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ', tr: "Allāhumma aʿinnī ʿalā dhikrika wa shukrika wa ḥusni ʿibādatik.", fr: "Ô Allah, aide-moi à T'évoquer, à Te remercier et à bien T'adorer.", ref: "Abu Dawud n°1522 ; An-Nasa'i n°1303 (sahih)" },
  'hamm': { titre: "Contre l'anxiété et la paresse", theme: 'Détresse', ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ، وَغَلَبَةِ الرِّجَالِ', tr: "Allāhumma innī aʿūdhu bika mina l-hammi wa l-ḥazan, wa l-ʿajzi wa l-kasal, wa l-bukhli wa l-jubn, wa ḍalaʿi d-dayn, wa ghalabati r-rijāl.", fr: "Ô Allah, je cherche refuge auprès de Toi contre le souci et la tristesse, l'incapacité et la paresse, l'avarice et la lâcheté, le poids des dettes et la domination des hommes.", ref: 'Al-Bukhari n°6369' },
  'taawudh': { titre: 'Chercher refuge contre Shaytan', theme: 'Protection', ar: 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', tr: "Aʿūdhu bi-Llāhi mina sh-shayṭāni r-rajīm.", fr: "Je cherche refuge auprès d'Allah contre Shaytan le maudit.", ref: "Coran, An-Nahl 16:98 ; Al-Bukhari n°6115 (face à la colère)" },
  'kaffara-majlis': { titre: "Expiation d'une assemblée", theme: 'Langue', ar: 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ', tr: "Subḥānaka Llāhumma wa bi-ḥamdik, ash-hadu an lā ilāha illā anta, astaghfiruka wa atūbu ilayk.", fr: "Gloire et louange à Toi, ô Allah. J'atteste qu'il n'y a de divinité que Toi. Je Te demande pardon et je me repens à Toi.", ref: 'At-Tirmidhi n°3433 (sahih)' },
  'sans-rancoeur': { titre: 'Pour un cœur sans rancœur', theme: 'Cœur', ar: 'رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ', tr: "Rabbanā ghfir lanā wa li-ikhwāninā lladhīna sabaqūnā bi-l-īmān, wa lā tajʿal fī qulūbinā ghillan li-lladhīna āmanū, rabbanā innaka ra'ūfun raḥīm.", fr: "Seigneur, pardonne-nous ainsi qu'à nos frères qui nous ont précédés dans la foi, et ne mets dans nos cœurs aucune rancœur envers ceux qui ont cru. Seigneur, Tu es Compatissant et Très Miséricordieux.", ref: 'Coran, Al-Hashr 59:10' },
  'parents': { titre: 'Pour les parents', theme: 'Famille', ar: 'رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا', tr: "Rabbi rḥamhumā kamā rabbayānī ṣaghīrā.", fr: "Seigneur, fais-leur miséricorde comme ils m'ont élevé tout petit.", ref: "Coran, Al-Isra 17:24" },
  'famille': { titre: 'Pour sa famille', theme: 'Famille', ar: 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', tr: "Rabbanā hab lanā min azwājinā wa dhurriyyātinā qurrata aʿyun, wa jʿalnā li-l-muttaqīna imāmā.", fr: "Seigneur, donne-nous, en nos épouses et nos descendants, la joie des yeux, et fais de nous un guide pour les pieux.", ref: 'Coran, Al-Furqan 25:74' },
  'dunya-akhira': { titre: "Le bien ici-bas et dans l'au-delà", theme: 'Général', ar: 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', tr: "Rabbanā ātinā fi d-dunyā ḥasanatan wa fi l-ākhirati ḥasanatan wa qinā ʿadhāba n-nār.", fr: "Seigneur, accorde-nous une belle part ici-bas et une belle part dans l'au-delà, et protège-nous du châtiment du Feu.", ref: 'Coran, Al-Baqara 2:201 ; invocation fréquente du Prophète ﷺ (Al-Bukhari n°6389)' },
  'hasbuna': { titre: 'La confiance en Allah', theme: 'Détresse', ar: 'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', tr: "Ḥasbunā Llāhu wa niʿma l-wakīl.", fr: "Allah nous suffit ; Il est notre meilleur garant.", ref: "Coran, Al 'Imran 3:173 ; Al-Bukhari n°4563" },
  'deux-paroles': { titre: 'Deux paroles lourdes dans la balance', theme: 'Dhikr', ar: 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ', tr: "Subḥāna Llāhi wa bi-ḥamdih, subḥāna Llāhi l-ʿaẓīm.", fr: "Gloire et louange à Allah, gloire à Allah l'Immense.", ref: 'Al-Bukhari n°6406 ; Muslim n°2694' },
  'tawakkul-sortie': { titre: 'En sortant de chez soi', theme: 'Protection', ar: 'بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', tr: "Bismi Llāh, tawakkaltu ʿala Llāh, wa lā ḥawla wa lā quwwata illā bi-Llāh.", fr: "Au nom d'Allah, je place ma confiance en Allah ; il n'y a de force ni de puissance qu'en Allah.", ref: "Abu Dawud n°5095 ; At-Tirmidhi n°3426" },
}

export const quranLink = (v) => `https://quran.com/${v.s}/${String(v.a).split('-')[0]}`
export const sunnahLink = (h) => `https://sunnah.com/search?q=${encodeURIComponent(h.fr.slice(0, 60))}`
export const verseRef = (v) => `${v.sourate} ${v.s}:${v.a}`
